WFJ.Data.add("gossip", {
  ["d8007068d6ce4f9a"] = { "Keever è molto compiaciuto.", "." },
  ["d804d26a428b14f6"] = { "La pazienza, <ragazzo/ragazza>, è la virtù più bella della terra. Ha visto montagne sgretolarsi e fiumi scavare valli: lenta e testarda, come un vero {race}. Ora la terra ti chiama, perché all'orizzonte si prepara qualche guaio. Torna con un successo e sarai un passo più vicin<o/a> a essere complet<o/a>.\n\nAltri potranno invidiare la tua saggezza, ma quello è un fardello che tocca a loro portare.", "." },
  ["d805d55fd1573d9c"] = { "{name}, hai idea di cosa ci aspetta nella ⟦Alterac Valley=Valle d'Alterac⟧? Sei <pronto/pronta> a combattere il ⟦Frostwolf Clan=Clan Lupi Bianchi⟧?", "." },
  ["d80942942c68aafb"] = { "È tutto perduto!", "." },
  ["d8104e33ff3ebea9"] = { "%s consegna il suo zaino a Quae.", "." },
  ["d8192b9f5edc7548"] = { "Il re è morto - OH NOOO! Chiamate Mizzle da Crafty! Lui sa cosa fare!", "." },
  ["d81f0eb1ffe3251b"] = { "%s recita una preghiera.", "." },
  ["d8211db194c0167d"] = { "Scappate pure, codardi! Non vi servirà a niente!", "." },
  ["d826508f7a4e2a22"] = { "Il mio lavoro qui è tutt'altro che finito, {name}. E devo mandare notizie a mia moglie Claira al ⟦Aerie Peak=Picco dell'Aquila⟧... e aggiornare anche Falstad.\n\nMa sono affari miei. Per te non è ancora tempo del viaggio di ritorno.\n\nComunque, dovresti informare di tutto questo re Magni Barbabronzea a ⟦Ironforge=Forgiardente⟧. Le ⟦Wetlands=Paludi Grigie⟧ sono a un tiro di sasso dalle sue terre, e niente di quel che succede qui è una bella notizia da trovarsi sulla soglia di casa. Questa lettera dovrebbe bastare.\n\nPuoi tornare passando per Dun Algaz o volare dal ⟦Menethil Harbor=Porto di Menethil⟧ per arrivare a ⟦Ironforge=Forgiardente⟧.", "." },
  ["d826708a981d94b1"] = { "<Un/Una> {race} ancora in vita... che presto sarà senza vita come me.", "." },
  ["d828501760d715ca"] = { "Voglio chiederti un'altra cosa.", "." },
  ["d82aeff50c3a7600"] = { "Pane fresco, sfornato proprio stamattina.", "." },
  ["d82cfa90f5ca0b91"] = { "Che c'è?", "." },
  ["d82d17ab425f3d5f"] = { "Hai fallito!", "." },
  ["d82f03fd13aa92fa"] = { "Non avrai mica pensato di trovare un villaggio senza un minatore residente, eh? Yarr di solito lo trovi allo ⟦Steelgrill's Depot=Scalo di Grigliafredda⟧, appena fuori Kharanos.", "." },
  ["d82f10ac2782514d"] = { "Che dolce ironia: le forze di ⟦Stormwind=Roccavento⟧, cadute in difesa della loro città, solo per rialzarsi e combattere a fianco della Fratellanza come strumenti di distruzione.", "." },
  ["d83815ee9fc1b275"] = { "L'anziano Cigliatonanti molto probabilmente si trova nel villaggio di ⟦Goldshire=Borgodoro⟧, nella ⟦Elwynn Forest=Foresta di Elwynn⟧.", "." },
  ["d839028482ac450d"] = { "Istruttori di Stregoni in ⟦Magic Quarter=Quartiere della Magia⟧, in edificio su anello esterno con maghi.", "." },
  ["d8391e82bffd74b4"] = { "C'è un maestro delle viverne nella grande città di ⟦Thunder Bluff=Picco del Tuono⟧, a nord. Prendi l'ascensore dalla base di ⟦Thunder Bluff=Picco del Tuono⟧ fino in cima e chiedi ulteriori istruzioni a uno dei Guardiani del Picco.", "." },
  ["d83a04ead2afff26"] = { "Aku'mai ha bisogno di altri innocenti per saziarsi.", "." },
  ["d84001ed855e7303"] = { "Che giornata per pescare. Oggi abboccheranno di sicuro!", "." },
  ["d844284904353cbf"] = { "%s lancia un grido acuto.", "." },
  ["d845bbce7b178788"] = { "Devi essere <Osannato/Osannata> presso gli orchi di Orgrimmar prima che io ti insegni a cavalcare, {class}.", "." },
  ["d85aad6b59ff6933"] = { "Aiuto! {name} non mi si stacca di dosso!", "." },
  ["d861c9b34472df40"] = { "Saremo di nuovo insieme, amore mio...", "." },
  ["d86ff5ef8058cd50"] = { "Non dimenticare di prendere la mia campanella dal forziere qui. E ricorda, se per caso ti allontani, suonala e ti ritroverò.", "." },
  ["d8766164da0133ac"] = { "Da questa parte. Fate attenzione, amici. Sento che Naralex si agita nel suo sonno tormentato....", "." },
  ["d8772bb58a5c34a0"] = { "Ti ho insegnato tutto ciò che posso per ora, <dottor/dottoressa> {name}. Torna da me quando la tua pratica si sarà ampliata e ti addestrerò nelle arti mediche più avanzate.", "." },
  ["d8839eeed63ebb51"] = { "Ah, finalmente aria fresca! Ho bisogno di riposare un momento, {name}.", "." },
  ["d883c07081fedc08"] = { "<Signorino/Signorina>, se non ti conoscessi meglio, penserei che sei <uno/una> di quei tipi 'speciali'. Noi li chiamiamo Trogg.\n\nWindsor non aveva niente contro i ⟦Dark Iron=Ferroscuro⟧, dopotutto il miglior amico del suo trisnonno era un ⟦Dark Iron=Ferroscuro⟧. Ed è probabilmente anche per questo che quell'esercito di ⟦Dark Iron=Ferroscuro⟧ non l'ha ammazzato a vista.", "." },
  ["d89488162d014d92"] = { "Oh, il tram, il tram... tutti vogliono salire sul tram. Che fine hanno fatto i bei vecchi tempi in cui si volava in groppa a un grifone, aggrappati alla sella per la vita mentre si sfrecciava alti nel cielo?\n\nBah! E allora vai a prendere il tram... è a Tinker Town, insieme al resto degli aggeggi gnomeschi.", "." },
  ["d89712a49110970c"] = { "Il cucito richiede una mano ferma. E pazienza... soprattutto pazienza.", "." },
  ["d8a1a5542ade9a8b"] = { "Sei riuscit<o/a> ad aiutare A-Me? Il rivestimento di mithril distrutto di cui parlavi era una buona ipotesi sul guasto. Sono sicura che se lo sostituisci si riattiverà e potrà tornare a casa.", "." },
  ["d8a66fc35f87bf77"] = { "Jin'rokh, temo di aver perso il mio ⟦Zandalar Vindicator's Breastplate=Pettorale Corazzato del Vendicatore degli Zandalari⟧. Puoi darmene uno nuovo?", "." },
  ["d8acbba972394c6c"] = { "%s si contorce dal dolore.", "." },
  ["d8ad46ebd042276f"] = { "Salve, {name}. Ti do il benvenuto a Thelsamar e, già che sei qui, non dimenticare di visitare la nostra birreria!", "." },
  ["d8b041f1def26fa2"] = { "AVANTI! VERSO AHN'QIRAJ!", "." },
  ["d8b20a86c3bb7a0c"] = { "Il genio è spesso frainteso, {race}. Ora, riguardo al frammento dello scettro... Se vuoi quel frammento e non desideri passare i prossimi diecimila anni a cercarlo, dovrai ascoltare con molta attenzione.", "." },
  ["d8b4183b9cf57fd8"] = { "%s posa la pergamena sul tavolo e legge...", "." },
  ["d8b5f184e91414dd"] = { "%s fugge dal combattimento per cercare aiuto!", "." },
  ["d8bf2928c1ccf95c"] = { "Tu deve andare in The Apothecarium in anello interno. Là Martha Alliestar insegna te come raccogliere fiori.", "." },
  ["d8c37672748c3d95"] = { "È giunto il momento di scuotere il mondo fin dalle fondamenta! È ORA il momento di ricordare a chi vorrebbe renderci schiavi che non ci piegheremo mai!", "." },
  ["d8d4c0266d70f8bf"] = { "Ritira le tue truppe, fratello, e ti prometto una seconda morte rapida!", "." },
  ["d8d653c9980bd9f4"] = { "Sei qui per aiutare con il cuoio pesante per la guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧, vero, {class}? Bene, bene. Come vedi ne ho raccolti $2066w, ma ce ne serviranno $2067w in tutto. È un bel po' di scuoiatura, amico mio, quindi spero che il tuo coltello sia affilato. Il cuoio servirà per ogni genere di uso, per fabbricare il nostro materiale bellico e garantire il nostro successo.", "." },
  ["d8db604a02163846"] = { "Se abbiamo istruttori di Estrazione qui? Ma dove credi di essere!?\n\nTroverai uno dei migliori minatori di tutto Dun Morogh alla Deepmountain Mining Guild, sul lato nord della ⟦Great Forge=Grande Forgia⟧. Lì ⟦Geofram Bouldertoe=Geofram Granditone⟧ ti mostrerà la vera arte dell'estrazione.", "." },
  ["d8e2228c670cafc1"] = { "Le giornate si fanno lunghe, e ancora non si vede la fine dei conflitti di queste terre. Non serve la magia per capirlo. Impugna una lama finché puoi, {class}. La guerra può arrivare alle nostre porte in qualsiasi momento e, se non sbaglio, mi sembri <uno/una> che ci sguazza.", "." },
  ["d8e3ec5258026c60"] = { "Sì, il gran signore Mograine: uno dei fondatori dell'ordine originale della ⟦Scarlet Crusade=Crociata Scarlatta⟧. Un cavaliere di fede e purezza incrollabili; Mograine sarebbe stato tradito dal suo stesso figlio e ucciso dalle forze di Kel'Thuzad dentro Stratholme. È così che mi ritrovo qui...", "." },
  ["d8f21ae016c79149"] = { "L'⟦Alliance=Alleanza⟧ ha conquistato la fattoria!", "." },
  ["d8fefaaea6a25172"] = { "%s perde vigore!", "." },
})
